def normalize_exercise_name(v):return " ".join("".join(c.lower() if c.isalnum() else " " for c in str(v or "")).split())
def movement_family_label(v):return MOVEMENT_FAMILY_LABELS.get(v,str(v or "").replace("_"," ").title())
def get_angle_options(f):return list(ANGLE_OPTIONS.get(f,[]))
def catalog_match(name):
 n=normalize_exercise_name(name)
 for x in BUILTIN_EXERCISE_CATALOG:
  if n==normalize_exercise_name(x["name"]):return {"item":x,"source":"canonical"}
  if n in [normalize_exercise_name(a) for a in x.get("aliases",[])]:return {"item":x,"source":"alias"}
 return None
def rank_catalog_candidates(name,category=None,family=None,equipment=None,angle=ANGLE_NOT_SPECIFIED,limit=8):
 tokens=set(normalize_exercise_name(name).split());out=[]
 for x in BUILTIN_EXERCISE_CATALOG:
  score=0;why=[];xt=set(normalize_exercise_name(x["name"]).split())
  if tokens&xt:score+=7*len(tokens&xt);why.append("name terms")
  if category and x["category"]==category:score+=20;why.append("same category")
  if family and x["family"]==family:score+=40;why.append("same family")
  if equipment and x["equipment"]==equipment:score+=15;why.append("same equipment")
  if angle!=ANGLE_NOT_SPECIFIED and x.get("angle")==angle:score+=15;why.append("same angle")
  if score:out.append({"item":x,"score":score,"reasons":why})
 return sorted(out,key=lambda y:(-y["score"],y["item"]["name"]))[:limit]


